  str_extra_mission_task_name_4500058 = "Cidade do Vento",
  str_extra_mission_task_name_4500059 = "No Final",
  str_extra_mission_task_name_4500060 = "Diferente da Primeira Vista",
  str_extra_mission_task_desc_4500001 = "Em algum lugar nos arredores de Lumópolis, a equipe de incursão da Rediesel Wrench passou derrubando tudo, cheia de equipamentos...",
  str_extra_mission_task_desc_4500002 = "Era óbvio que um grupo de soldados ordinários e inaptos não seria páreo para o Brock, cujo descontentamento era visível a quilômetros de distância.",
  str_extra_mission_task_desc_4500003 = "Com a intervenção de dois Guardiões e a própria Carleen, Brock finalmente foi “derrotado” e jogado na prisão de Lumópolis...",
  str_extra_mission_task_desc_4500004 = "A companheira inesperada, Jona, deu um jeito de escapar da prisão com Brock. Ela parecia doidinha demais, então vamos torcer pra que Jona não faça nenhuma loucura...",
  str_extra_mission_task_desc_4500005 = "Apenas Jona poderia pensar em pular de Lumópolis como uma rota de fuga. Diante de uma fuga ousada, os Guardiões podiam apenas vê-los fugir.",
  str_extra_mission_task_desc_4500006 = "Brock reuniu-se com sua equipe e, juntos, foram capazes de se encontrar com Regina, que veio prestar reforços. No entanto, um encontro com Eclipsitas estava acontecendo por perto, e todos se prepararam pra lutar.",
  str_extra_mission_task_desc_4500007 = "A cidade subterrânea de Illumina parece ter sido invadida por Eclipsitas, mas buscavam apenas a cauda de Sharona?!",
  str_extra_mission_task_desc_4500008 = "Mais uma vez, o convidado indesejado veio provocar Sharona, e dessa vez, algo importante parece ter sido roubado...",
  str_extra_mission_task_desc_4500009 = "Os dois começaram a localizar o inimigo. Precisam descobrir o que foi roubado. Essa jornada não estava sendo nada fácil...",
  str_extra_mission_task_desc_4500010 = "Sharona teve que proteger a Philyshy adormecida e lidar com os Eclipsitas que atacavam. Isso definitivamente não seria fácil.",
  str_extra_mission_task_desc_4500011 = "Quando acordou, Philyshy parecia meio estranha? E quem era “Yumi”? Sahrona hesitou diante do que viu...",
  str_extra_mission_task_desc_4500012 = "Philyshy, que conseguiu conter sua outra personalidade temporariamente e, finalmente lembrou que Bowlinger possuia o que procuravam!",
  str_extra_mission_task_desc_4500013 = "Era uma tarde de verão, e os amigos Connolly e Anton estavam limpando o porão da cafeteria, quando escutaram um misterioso grito de socorro...",
  str_extra_mission_task_desc_4500014 = "Aqueles que perturbam a ordem da guilda devem ser punidos severamente! Robyn e Dayna aceitaram a missão, determinados a capturar o criminoso.",
  str_extra_mission_task_desc_4500015 = "Em sua busca pelo gato robô, Connolly e Anton chegaram ao Centro de Transporte, e diante deles estavam os Guardas Lumo...",
  str_extra_mission_task_desc_4500016 = "A nova vítima é o proprietário do gato robô! Ele deve ter consumido a mistura. Temos que salvá-lo!",
  str_extra_mission_task_desc_4500017 = "Os Eclipsitas, escondidos nas sombras, roeram os membros da vítima inconsciente.",
  str_extra_mission_task_desc_4500018 = "Venda de suprimentos proibidos e ataques aos membros da Guilda! Temos que descobrir quem está por trás disso!",
  str_extra_mission_task_desc_4500019 = "Aqueles que ousarem entrar em Northland serão enterrados na neve frígida sem deixar vestígios.",
  str_extra_mission_task_desc_4500020 = "Carleen veio sozinha até Northland quando ainda nova. Ela foi recebida pelos ventos gelados, no lugar de aventuras românticas.",
  str_extra_mission_task_desc_4500021 = "Fracasso seguido de fracasso. Era um mero fantasma de eclipsita invocado com magia, mas surpreendentemente formidável.",
  str_extra_mission_task_desc_4500022 = "No pesadelo, Bethlehem reviveu seu passado quando Northland estava à beira de um colapso, enquanto vários eclipsitas a cercaram.",
  str_extra_mission_task_desc_4500023 = "Valeu insistir no treinamento. Identificar e aproveitar a fraqueza do inimigo, pode nos levar à vitória!",
  str_extra_mission_task_desc_4500024 = "Perfure o bloqueio final com a lança em suas mãos! A aurora esplendorosa se tornará a ponte que liga duas almas!",
  str_extra_mission_task_desc_4500001_long = "Em algum lugar nos arredores de Lumópolis, uma equipe de incursão da Rediesel Wrench passou derrubando tudo, carregando muito tesouros.\nMesmo quando encontraram a Patrulha de Lumópolis, seu capitão, Brock, não viu motivo pra pânico. De fato, pareciam estar ansiosos por uma luta.",
  str_extra_mission_task_desc_4500002_long = "Estava claro que um grupo de soldados ordinários e inaptos não seria páreo para o Brock, cujo descontentamento era visível a quilômetros de distância.\nEntretanto, com a intervenção de dois Guardiões e a própria Carleen, Brock finalmente foi derrotado.",
  str_extra_mission_task_desc_4500003_long = "Brock foi jogado na Prisão de Lumópolis, e aqui encontrou uma companheira inesperada, Jona,\nque, com um ar de indiferença, \ndestruiu a base e escapou com Brock!",
  str_extra_mission_task_desc_4500004_long = "Ela parecia meio doidinha, então vamos torcer pra que não faça nenhuma loucura...\nMas convenhamos, ela pulou diretamente de Lumópolis com Brock.\nCertamente uma tentativa de fuga meio suicida.",
  str_extra_mission_task_desc_4500005_long = "Diante uma fuga tão ousada, os Guardiões ficaram sem ação.\nBrock reuniu sua equipe, e juntos, foram capazes de se encontrar com Regina, que veio prestar reforços. No entanto, um encontro com Eclipsitas estava acontecendo por perto, e todos se prepararam pra lutar.",
  str_extra_mission_task_desc_4500006_long = "Coincidentemente, os Guardiões também foram atraídos para a algazarra, e ambos os lados concordaram em relevar as diferenças e lutar contra o inimigo em comum.\nDepois da batalha,\nquando encarou Sinsa, a líder da Rediesel Wrench, Carleen hesitou em agir,\ne ficou apenas observando, enquanto os lunáticos se retiravam...",
  str_extra_mission_task_desc_4500007_long = "Na cidade subterrânea de Illumina, Sharona acordou por um visitante inesperado, \nque parecia estar ali só pra brincar com sua cauda?\nO local foi invadido por inimigos?\nO que estava acontecendo?",
  str_extra_mission_task_desc_4500008_long = "O misterioso visitante retornou, e Sharona o perseguiu, mas seria apenas uma distração?\nDepois de derrotar seus vassalos, Sharona retornou à Sala de Inteligência e viu Philyshy adormecida...\nNão só Sharona teve que aceitar a Philyshy perdendo anotações, agora teriam que trabalhar juntas?!",
  str_extra_mission_task_desc_4500009_long = "Philyshy achou a passagem secreta por pura sorte.\nPhilyshy, que protegeu Sharona, conseguiu mudar a opinião de Sharona a seu respeito.",
  str_extra_mission_task_desc_4500010_long = "Quando o embate estava finalmente acontecendo, Philyshy mal conseguia se manter acordada!\nInimigos que estavam espertos, a procura de aberturas, não perdoariam esse desleixo.\nEnquanto Sharona protegia a pequena, parecia estar se apegando à ela...",
  str_extra_mission_task_desc_4500011_long = "Depois de acordar, Philyshy parecia uma pessoa completamente diferente, cruel e excêntrica.\nSharona imediatamente a identificou como a “Eclipsita” que a estava incomodando!\nIsso aconteceu devido ao transtorno de personalidade da Philyshy?\nPara acordar Philyshy, Sharona teve que usar sua cauda pra “cutucar a onça”.",
  str_extra_mission_task_desc_4500012_long = "Finalmente, Philyshy e Sharona chegaram juntas ao fim da passagem secreta, determinadas em recuperar o precioso item roubado: que era uma lata de sardinha?!\nParece que sob, a influência de Yumi, o plano do inimigo falhou desde o início...\nSharona e Philyshy, por outro lado, foram abençoadas com uma amizade extraordinária por causa dessa experiência louca...\nE o Eclipsita de alto nível que apareceu em Illumina foi...?",
  str_extra_mission_task_desc_4500013_long = "Era uma tarde de verão, Connolly e Anton limpavam o porão da cafeteria.\nConnolly estava revivendo memórias do passado depois de achar uma partitura musical chamada – Lar – no porão, quando um grito de socorro veio do que parecia ser\num gato robô.",
  str_extra_mission_task_desc_4500014_long = "O homem misterioso que vendeu a poção misteriosa e destruiu a ordem da guilda escapou!\nDepois de falharem em sua missão, Dayna e Robyn foram ao Café Holiday para uma pausa.\nDayna consertou o gato robô de Connolly com força bruta,\nmas antes que pudesse aproveitar seu brinquedo fofinho, receberam uma nova missão:\nE o gato também desapareceu misteriosamente.",
  str_extra_mission_task_desc_4500015_long = "Perseguindo o gato robô, Connolly e Anton chegaram ao Centro de Transporte. \nFoi aqui que encontraram o dono do gato robô,\num homem ansioso para entrar em Lumópolis, não importasse o preço.",
  str_extra_mission_task_desc_4500016_long = "As palavras de Sheol deixaram Connolly mergulhada em pensamentos, imersa em seu próprio mundo,\nsem notar que todos Umbraton eram também sua família.\nUma mensagem apareceu no transmissor de Dayna: uma nova vítima apareceu!\nDeterminada a conseguir a ajuda de todos, Connolly escreveu uma mensagem para sua família no quadro negro.",
  str_extra_mission_task_desc_4500017_long = "Apesar do dono do gato ter bebido a mistura, ele ainda assim morreu e virou jantar de Eclipsitas.\nEm suas alucinações, viu os portões de Lumópolis abrirem à sua frente, \nmas o vazio em seu coração ainda permanecia.\nAfinal de contas, Lumópolis nunca fora sua casa.",
  str_extra_mission_task_desc_4500018_long = "O Eclipsita que vendeu a mercadoria proibida teve o que mereceu.\nNo entanto, a casa do mecânico e seu gato desmoronou, e ele confiou o gato aos cuidados de Connolly.\nNão foi a Lumópolis perfeita que salvou Connolly, mas todos ao seu redor!\n“Obrigado! Vamos voltar à cafeteria e tomar um cappuccino!”",
  str_extra_mission_task_desc_4500019_long = "Northland é um reino em que a neve nunca derrete.\nO poder devastador da neve e do gelo tornou a Rainha do Norte invencível contra quaisquer invasores.\nNo entanto, o mesmo poder a aprisionou ali. \nCom uma nevasca inesperada, \numa forasteira chegava.",
  str_extra_mission_task_desc_4500020_long = "“Não faça nada inapropriado.”\nO pai fizera preparativos para mandar Carleen à Northland sozinha.\nA rainha parecia distante, deslocada, fria como gelo.\nComo um forasteiro em terras desconhecidas, Carleen sentiu a solidão e o frio em seus ossos.",
  str_extra_mission_task_desc_4500021_long = "Podia ser algum tipo de profecia.\nBethlehem percebeu isso. A aurora, clara mas fosca, brilhava na escuridão sem-fim da noite.\nNa tempestade, a jovem Carleen tentou atacar o fantasma eclipsita, de novo e de novo.\nSó terminou em mais fracassos.",
  str_extra_mission_task_desc_4500022_long = "O pesadelo esquecido ressurgia. Bethlehem viu o fantasma de si mesma.\nAlém disso, ela viu Carleen.\n“O poder vem acompanhado de solidão”. Mesmo assim, Bethlehem aceitou o poder da neve e do gelo.\nMas e Carleen? Que caminho, na mesma bifurcação, ela deveria trilhar?",
  str_extra_mission_task_desc_4500023_long = "Tornar-se poderosa requer grande esforço.\nDa mesma forma, a cristalização de um lindo floco de neve requer frio extremo.\nCarleen fez isso.\nCom um sorriso de satisfação em seu rosto, Bethlehem pediu à Carleen para se preparar para o “verdadeiro teste”...",
  str_extra_mission_task_desc_4500024_long = "Foi a primeira vez que Carleen derrotou um eclipsita sozinha. \nDepois da tensão, Bethlehem gentilmente acariciou o rosto da garota.\nFez um gesto para a aurora esplendorosa.\nPara proteger a aurora, ela escolheu o poder e a solidão por vontade própria.\nCarleen dividia esse sentimento, por isso trilhou o mesmo caminho para proteger Lumópolis.",
  str_extra_mission_dec_0001 = "Era uma tarde preguiçosa, e a melodia de \"Casa\" fluía  da velha e amarelada partitura. Das ruas de Umbraton, uma menina tímida, Connolly, olhava para Lumópolis. Era um palácio magnífico, um paraíso para os devotos e um lugar para morar, mas não era um lar, especialmente para uma viajante solitária...",
  str_extra_mission_dec_0002 = "Já era tarde da noite em Gannon e, como o resto de Illumina, Sharona estava dormindo até que \"alguém\" encostou em sua cauda. Essa estranha perturbação durou vários dias, e quando a irritada Sharona finalmente conseguiu rastrear seu agressor, acabou ganhando uma companheira ainda mais problemática, Philyshy...",
  str_extra_mission_dec_0003 = "Era uma tarde preguiçosa, e a melodia fluía de... Casa... da velha e amarelada partitura. Das ruas de Umbraton, uma menina tímida, Connolly, olhava para Lumópolis. Era um palácio magnífico, um paraíso para os devotos e um lugar para morar, mas não era um lar, especialmente para uma viajante solitária...",
  str_extra_mission_dec_0004 = "Coberta por gelo e neve, Northland esteve isolada do mundo por gerações. O portão do palácio da rainha estava fechado, assim como seu coração gélido. Porém, aquele portão pesado foi aberto inesperadamente por um floco de neve, pequeno e constante, sempre admirando a aurora."
}
return config
